import{D as e,G as t,O as n,j as r,k as i,tt as a,w as o,x as s}from"./BetWqH3h.js";import{t as c}from"./CMGTFL-s.js";import{n as l,r as u}from"#entry";var d=u(`/images/020.png`),f={class:`content`},p={class:`title`},m=r({__name:`femto-7`,setup(r){return l({title:`FEMTO-7 - Projects - ajbkr.com`}),(r,l)=>{let u=c;return t(),o(`div`,f,[s(`h1`,p,[i(u,{class:`projects__link`,to:`/projects/`},{default:a(()=>[...l[0]||=[n(`Projects`,-1)]]),_:1})]),l[1]||=e(`<h3 id="FEMTO_7_PICO_8_like_Standalone_Library_for_C_CPP"> FEMTO-7: PICO-8-like Standalone Library for C/C++ </h3><p> I really love the look and feel of the <a href="https://www.lexaloffle.com/pico-8.php" rel="noopener" target="_blank"> PICO-8 fantasy console; </a> with its extremely limited 128x128 resolution and 16-colour fixed palette, those low-fidelity constraints prove ideal for encouraging the PICO-8 game developer to be especially creative and inventive. </p><p> What I&#39;m less keen on, is programming in Lua. Honestly, I don&#39;t think learning to code and program in Lua is a terrible thing to do, it&#39;s just that I would far rather invest my time and effort continuing to code simple game prototypes in languages with which I am more familiar... like C/C++ (or JavaScript). </p><p> And then, if a game&#39;s mechanics appear promising and I decide to make a full-fledged game, I can easily re-use significant quantities of the code that I will have already written. </p><p>Enter stage left: FEMTO-7!</p><img class="image my-5" alt="Screenshot of a FEMTO-7 demo" title="FEMTO-7 demo" width="514" height="544" loading="lazy" src="`+d+`"><p> FEMTO-7 is my standalone PICO-8-like library for C/C++. It&#39;s written in ANSI C and uses <a href="https://www.raylib.com/" rel="noopener" target="_blank"> raylib </a> (version 5.0) to provide fantasy console functionality on Linux, macOS, and Windows; the build is driven by CMake, with vcpkg handling dependencies. </p><p> The name is a small joke: the metric prefix &quot;femto&quot; is three orders of magnitude below &quot;pico&quot;, and 7 is one less than 8, so I&#39;ve landed on something a little more modest than the console that inspired it. </p><p>Currently implemented functions include:</p><ul><li><tt>abs()</tt> - returns the absolute value of a number</li><li><tt>atan2()</tt> - calculates the arctangent of dy/dx</li><li><tt>btn()</tt> - test if a button is being pressed at this moment</li><li><tt>btnp()</tt> - test if a button has just been pressed, <s>with keyboard-style repeating</s></li><li><tt>camera()</tt> - set a screen offset applied to all subsequent draw operations </li><li><tt>ceil()</tt> - returns the nearest integer at or above a number (its &quot;ceiling&quot;) </li><li><tt>circ()</tt> - draw a circle shape, without fill</li><li><tt>circfill()</tt> - draw a filled-in circle shape</li><li><tt>clip()</tt> - set the screen clipping region for subsequent draw calls </li><li><tt>cls()</tt> - clear the graphics buffer</li><li><tt>color()</tt> - set the draw colour in the draw state</li><li><tt>cos()</tt> - calculates the cosine of an angle</li><li><tt>cursor()</tt> - set the left-margin cursor position for <tt>print()</tt></li><li><tt>fget()</tt> - get the flags of a sprite</li><li><tt>fillp()</tt> - set the fill pattern used by the shape-drawing functions </li><li><tt>flip()</tt> - copy the graphics buffer to the screen, then synchronise to the next frame at 30 frames per second </li><li><tt>flr()</tt> - returns the nearest integer at or below a number (its &quot;floor&quot;) </li><li><tt>fset()</tt> - set the flags of a sprite</li><li><tt>line()</tt> - draw a line between two points</li><li><tt>map()</tt> - draw a portion of the map to the graphics buffer</li><li><tt>max()</tt> - returns the maximum of two numbers</li><li><tt>mget()</tt> - gets the sprite number assigned to a cell on the map </li><li><tt>mid()</tt> - returns the middle of three numbers</li><li><tt>min()</tt> - returns the minimum of two numbers</li><li><tt>mset()</tt> - sets a cell on the map to a new sprite number</li><li><tt>music()</tt> - plays a music pattern, or stops playing</li><li><tt>pal()</tt> - change the draw state so all instances of a given colour are replaced with a new colour </li><li><tt>palt()</tt> - change the transparency of a colour in the draw state for subsequent draw calls </li><li><tt>pget()</tt> - get the colour value of a pixel at the given coordinates </li><li><tt>print()</tt> - print a string of characters to the screen</li><li><tt>printh()</tt> - prints a string to a console window that is running FEMTO-7 </li><li><tt>pset()</tt> - set a pixel in the graphics buffer</li><li><tt>rect()</tt> - draw an empty rectangle shape</li><li><tt>rectfill()</tt> - draw a filled-in rectangle shape</li><li><tt>rnd()</tt> - generates a random number under the given limit, <s>or returns a random element from a sequence</s></li><li><tt>rotl()</tt> - rotate the bits of an integer left</li><li><tt>rotr()</tt> - rotate the bits of an integer right</li><li><tt>sfx()</tt> - plays a sound effect</li><li><tt>sget()</tt> - gets the colour value of a pixel on the sprite sheet </li><li><tt>sgn()</tt> - returns the sign of a number</li><li><tt>sin()</tt> - calculates the sine of an angle</li><li><tt>spr()</tt> - draw a sprite, or a range of sprites, on the screen </li><li><tt>sqrt()</tt> - calculates the square root of a number</li><li><tt>srand()</tt> - initialises the random number generator with an explicit seed value </li><li><tt>sset()</tt> - sets the colour value of a pixel on the sprite sheet </li><li><tt>stat()</tt> - returns information about the current runtime environment </li><li><tt>t()</tt> - alias of <tt>time()</tt></li><li><tt>time()</tt> - returns the amount of time since FEMTO-7 was last started </li></ul><p> I&#39;m only chasing PICO-8&#39;s drawing, input, audio, and math functions, which is all I need to knock together a game prototype. There&#39;s no Lua runtime, and I&#39;ve skipped its <tt>peek()</tt>/<tt>poke()</tt> memory model and its string and table helpers. Most of PICO-8&#39;s bitwise functions (<tt>band()</tt>, <tt>shr()</tt> and friends) are gone too: Lua needs them because it has no bitwise operators of its own, but C and JavaScript both do, so there&#39;s nothing to replace. I&#39;ve kept <tt>rotl()</tt> and <tt>rotr()</tt>, since neither language has an operator for bit rotation. </p><p> To stop FEMTO-7 drifting away from the thing it&#39;s imitating, I&#39;ve ported a handful of zep&#39;s original PICO-8 demos (hello, bounce, dots3d, a raycaster, drippy, sort, and waves), rewriting each one in JavaScript. I also have a set of test programs that draw a shape in FEMTO-7 and compare the result, pixel-for-pixel, against the same thing captured from real PICO-8, plus unit tests covering the maths. </p><p> FEMTO-7 can even be compiled to a shared or dynamic library for Linux (libf7.so), macOS (libf7.dylib), and Windows (libf7.dll) and accessed from a whole host of other programming languages using FFI. Bindings already exist for <a href="https://deno.com/" rel="noopener" target="_blank">Deno,</a> an alternative runtime for JavaScript. </p><p> I might one day put out an early access version of FEMTO-7 on <a href="https://itch.io/" rel="noopener" target="_blank">itch.io</a>, though it&#39;s not something I&#39;ve firmly decided on. </p>`,14)])}}});export{m as default};